contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address who) public payable {
        require(true);
        c.XBornID(); if (__ESBMC_reverted()) return;
        assert(c.balanceOf(who) == (who == address(this) ? c.totalDistributed() : 0));
    }
    receive() external payable {}
}

